fn diagnostic_ref(text : String) -> Bool {
  text.length() <= 1024 &&
  !text.has_prefix("-") &&
  !text.contains("..") &&
  text
  .split("/")
  .iter()
  .all(part => {
    part != "" &&
    !part.has_prefix(".") &&
    !part.has_suffix(".") &&
    !part.has_suffix(".lock")
  }) &&
  text
  .iter()
  .all(c => {
    (c >= 'a' && c <= 'z') ||
    (c >= 'A' && c <= 'Z') ||
    (c >= '0' && c <= '9') ||
    c == '/' ||
    c == '-' ||
    c == '_' ||
    c == '.'
  })
}

