import type { Repo } from '../../../shared/repo-types'
import {
  SSH_TARGET_MANAGEMENT_RUNTIME_CAPABILITY,
  type SshEditableTarget,
  type SshEditableTargetAddResult,
  type SshEditableTargetInput
} from '../../../shared/ssh-target-management'
import type { FilesystemPathFlavor } from '../../../shared/filesystem-entry-types'
import { callRuntimeRpc, runtimeEnvironmentSupportsCapability } from './runtime-rpc-client'

/** The paired server predates server SSH management; the caller shows "update the server". */
export class RuntimeSshTargetManagementUnsupportedError extends Error {
  constructor() {
    super('Update this Orca server to manage its SSH hosts from here.')
    this.name = 'RuntimeSshTargetManagementUnsupportedError'
  }
}

export function runtimeSupportsSshTargetManagement(environmentId: string): Promise<boolean> {
  return runtimeEnvironmentSupportsCapability(
    environmentId,
    SSH_TARGET_MANAGEMENT_RUNTIME_CAPABILITY
  )
}

// Why every call checks: an old server would answer method_not_found at best; there is never a
// local fallback, because this client's own SSH hosts are a different machine's.
async function callSshTargetManagement<T>(
  environmentId: string,
  method: string,
  params?: unknown,
  timeoutMs?: number
): Promise<T> {
  if (!(await runtimeSupportsSshTargetManagement(environmentId))) {
    throw new RuntimeSshTargetManagementUnsupportedError()
  }
  return callRuntimeRpc<T>(
    { kind: 'environment', environmentId },
    method,
    params,
    timeoutMs === undefined ? {} : { timeoutMs }
  )
}

export async function listRuntimeEditableSshTargets(
  environmentId: string
): Promise<SshEditableTarget[]> {
  const result = await callSshTargetManagement<{ targets: SshEditableTarget[] }>(
    environmentId,
    'ssh.listEditableTargets'
  )
  return result.targets
}

export function addRuntimeSshTarget(
  environmentId: string,
  target: SshEditableTargetInput
): Promise<SshEditableTargetAddResult> {
  return callSshTargetManagement(environmentId, 'ssh.addTarget', { target })
}

export async function updateRuntimeSshTarget(
  environmentId: string,
  targetId: string,
  target: SshEditableTargetInput
): Promise<SshEditableTarget> {
  const result = await callSshTargetManagement<{ target: SshEditableTarget }>(
    environmentId,
    'ssh.updateTarget',
    { targetId, target }
  )
  return result.target
}

export async function removeRuntimeSshTarget(
  environmentId: string,
  targetId: string
): Promise<void> {
  await callSshTargetManagement(environmentId, 'ssh.removeTarget', { targetId })
}

export type RuntimeSshDirectoryListing = {
  entries: { name: string; isDirectory: boolean }[]
  resolvedPath: string
  pathFlavor: FilesystemPathFlavor
}

export function browseRuntimeSshDirectory(
  environmentId: string,
  targetId: string,
  dirPath: string
): Promise<RuntimeSshDirectoryListing> {
  // Why 20s: the server bounds its own SSH listing at 15s.
  return callSshTargetManagement(environmentId, 'ssh.browseDir', { targetId, dirPath }, 20_000)
}

export async function addRuntimeSshRepo(
  environmentId: string,
  args: { connectionId: string; remotePath: string; displayName?: string; kind?: 'git' | 'folder' }
): Promise<Repo> {
// Why: runtime clients can be CLI, desktop, or future non-Electron shells.
// Keeping the envelope contract here avoids making those clients import each
// other just to validate the shared RPC frame shape.
import { z } from 'zod'
import type { OrchestrationCompatibilityEvidence } from './orchestration-compatibility-evidence'

// Why: clients and runtimes update independently; strip additive envelope
// fields while continuing to validate every known discriminator and field.
const MetaSuccess = z
  .object({
    runtimeId: z.string()
  })
  .strip()

const MetaFailure = z
  .object({
    runtimeId: z.union([z.string(), z.null()])
  })
  .strip()
  .optional()

const Success = z
  .object({
    id: z.string(),
    ok: z.literal(true),
    result: z.unknown(),
    _meta: MetaSuccess
  })
  .strip()

const Failure = z
  .object({
    id: z.string(),
    ok: z.literal(false),
    error: z
      .object({
        code: z.string(),
        message: z.string(),
        data: z.unknown().optional()
      })
      .strip(),
    _meta: MetaFailure
  })
  .strip()

const Keepalive = z
  .object({
    _keepalive: z.literal(true)
  })
  .strip()

export const RuntimeRpcEnvelopeSchema = z.union([Success, Failure, Keepalive])

export type RuntimeRpcSuccess<TResult> = {
  id: string
  ok: true
  result: TResult
  _meta: {
    runtimeId: string
  }
}

export type RuntimeRpcFailure = {
  id: string
  ok: false
  error: {
    code: string
    message: string
    data?: unknown
  }
  _meta?: {
    runtimeId: string | null
  }
}

export type RuntimeRpcResponse<TResult> = RuntimeRpcSuccess<TResult> | RuntimeRpcFailure

export type RuntimeOrchestrationEnvelope = {
  orchestrationCapability?: string
  orchestrationContractVersion?: number
  orchestrationRequestId?: string
  compatibilityInvocationId?: string
  orchestrationCompatibilityEvidence?: OrchestrationCompatibilityEvidence
}

From https://github.com/atty303/orca-env-devsy
 * [new tag]         v0.2.2     -> v0.2.2
---
name: develop-repository
description: 開発、修正、リファクタリング、レビュー対応など、リポジトリを変更するタスクで、対象リポジトリに応じた観測可能な実装、検証、ドキュメントおよび再現性の方針を適用する。
---

# Development tasks

## Frame the work

- 変更は明示されたrepository内に限定する。依頼、適用guidance、sourceおよび実環境から目的、observableな成功条件、hard constraint、明示された手段、non-goalおよび未検証の前提をclosed setとして保持する。
- 設計・成果物の選択は共通guidanceの基本判断原則に従う。同じcontractとauthority内で、repo変更なし、削除、簡略化、既存機構の利用、既存成果物の変更、新規成果物を比較し、列挙順を固定順位にしない。前提崩壊により主要contractを変える必要があれば停止して確認する。
- 成果物の段階とcontrol domainは [artifact profile and control domain](../../references/artifact-profile-and-control-domain.md) で確定する。Repositoryへ残す変更は明示的なspike contractがない限り`durable`とする。
- 新規library、開発toolまたはtest packageは全repositoryで事前承認を必要とする。必要性、主要代替、保守・security・配布への影響を示し、承認前に追加も独自実装による迂回もしない。
- Repository固有の互換性方針を優先する。利用者によるmigration、data変換または選択が必要な破壊的変更は、影響と移行方法を示して実装前に確認する。

## Establish repository state

- 通常のGit commandだけを使う。Git repositoryでなければ停止し、別VCSを解釈、操作または初期化しない。
- 変更前にremoteがあればcodeをfetchし、branch、upstream、HEADと親、index、working tree、default branchおよび必要なdiffを確認する。Fetch失敗時はremote情報の陳腐化を明示する。
- Branchの作成・切り替えを判断する前にRepository profileを適用する。適用されるbranch方針がなければ、指定branchまたは依頼に対応する既存branchを優先する。無関係な変更から新しい作業を派生させず、rewrite、既存branch移動または未確定変更を伴う切替は確認する。
- 現在のsourceやliving documentationだけでは判断できない意図、未完了範囲またはmigrationがある場合は、関連path、schema、featureまたはcommitに限定してGit logと既存notesを調べる。履歴はdescriptiveであり現在の原典を上書きしない。
- 開発、build、test環境は現在のrepositoryのsource、task、build process、適用guidanceまたはユーザーの明示指定から確定する。承認済みcommand、memory、過去task、toolの存在または別用途のcontainer・runtimeだけを根拠に転用しない。
- 変更taskの開始時にrelease workflowの参照を軽く確認する。`uses: atty303/repository-template/.github/actions/release@...` とsemantic-releaseの直接実行・action参照を対象とし、前者は`versioning`入力で`semver`か`calver`かを分ける。通常はworkflowの稼働状況やrelease実装の内部を追わない。

## Agree on commit release impact

- 上記のrelease workflowを使うrepositoryではConventional Commitsを必須とする。Repository固有のtype、scope、文体など両立する慣習にも従い、release判定と矛盾する慣習があればcommit前に確認する。その他のrepositoryではConventional Commitsを推奨し、明示されたrepository慣習を優先する。
- 対象repositoryではrelease workflowを確認した直後、他の調査・実装へ進む前の利用者向け応答で、このtaskで作るcommit全体のrelease要否を提案・送信して承認を求める。SemVerなら最大bump（`major`/`minor`/`patch`/`none`）も、`versioning: calver`のactionならrelease要否だけを提案する。利用可能なら非同期の質問手段を使い、回答を待たずに承認済みの作業を進める。詳細が未確定でも現在の情報による暫定提案と不確実性を先に送り、判明後に変更が必要なら速やかに再提案する。既に利用者が明示した判断は再確認しない。複数commitのtype、scope、件数は承認範囲内で決める。既存の未リリースcommitが次回release全体に与える影響と、このtaskの上限は区別する。
- 現行の標準判定は、`feat`→minor、`fix`・`perf`・`revert`→patch、`docs`・`test`・`ci`・`build`・`chore`・通常の`refactor`→releaseなし、認識された`!`またはfooterの`BREAKING CHANGE:`→majorとする。通常taskでこの表を調べ直さない。判明しているrepository固有の`releaseRules`、preset、parser設定は優先する。`repository-template` actionは`revert:`と`!`を認識するが、semantic-releaseの直接利用では既定parserが`revert:`や`!`だけをrelease要因として認識するとは限らない。直接利用でそれらを使う場合は設定を確認し、必要なreleaseが確実に起きる記法を選ぶ。
- 現在の基準releaseが0.xなら、破壊的変更だけを理由にmajor記法を付けない。破壊的な`fix`も`fix`のままpatch、`feat`はminorとし、変更の実態と異なるtypeでbumpを調整しない。1.xへの移行は利用者の明示的な指示・承認がある場合だけ許す。0.xの基準releaseを確認できずrelease影響を確定できない場合は、そのcommitを保留する。
- 開始時の提案を送った後は回答待ちでも、commitなしで実施できる承認済みの実装、文書、検証、reviewなどをすべて進める。Releaseが必要なら少なくとも一つのcommitでreleaseを起こし、必要な修正を`chore`として抑えない。完成した変更が承認されたrelease要否・上限と合わなければ、残る作業を進めたうえで差を示し、commitを保留して判断を求める。

## Implement the selected durable change

- 既存format、生成元およびrepositoryの標準taskを使う。Generated fileとlockfileはownerを特定して正規手順で更新し、推測で手編集しない。
- 補助toolの設定はupstream標準をbaselineとし、依頼に必要な最小差分だけを持つ。成果物を経緯から切り離して読み、不要なcompatibility layer、旧経路、alias、分岐、commentおよびdocumentを残さない。
